function NEWTON_STEPS(target):
    require target >= 1
    return floor(log2(target)) + 1

function HENSEL_CERTIFICATE(target):
    s <- NEWTON_STEPS(target)
    p <- 2^s                      # precision lower bound
    assert p >= target            # Theorem: exponential precision
    assert s < target  if target >= 3   # Theorem: sublinear speedup
    return (s, p)

